def verify_webhook_signature(
    payload_bytes: bytes,
    signature_header: Optional[str],
    secret: str,
) -> bool:
    """Verify GitHub webhook signature using HMAC-SHA256.

    GitHub passes the header 'X-Hub-Signature-256' in the format 'sha256=<hex_digest>'.
    Uses hmac.compare_digest to prevent timing attacks.
    """
    if not signature_header or not secret:
        return False

    if not signature_header.startswith("sha256="):
        return False

    expected_hash = signature_header[7:].strip()
    if not expected_hash:
        return False

    computed_mac = hmac.new(
        key=secret.encode("utf-8"),
        msg=payload_bytes,
        digestmod=hashlib.sha256,
    ).hexdigest()

    return hmac.compare_digest(computed_mac, expected_hash)

def parse_source(
        self,
        code: str,
        file_path: str,
        language: Language,
    ) -> list[FunctionNode]:
        """Parse source code string into a list of FunctionNode AST representations."""
        code_bytes = code.encode("utf-8")

        if language == Language.PYTHON:
            tree = self._python_parser.parse(code_bytes)
            return self._extract_python_functions(tree.root_node, code_bytes, file_path)
        elif language in (Language.TYPESCRIPT, Language.JAVASCRIPT):
            tree = self._ts_parser.parse(code_bytes)
            return self._extract_typescript_functions(tree.root_node, code_bytes, file_path, language)
        else:
            return []

def parse_file(self, file_path: str | Path) -> list[FunctionNode]:
        """Read a file from disk and parse all function nodes."""
        path = Path(file_path)
        lang = detect_language(str(path))
        if not lang:
            return []

        code = path.read_text(encoding="utf-8", errors="replace")
        return self.parse_source(code, str(path), lang)

def traverse(node: Node, current_class: Optional[str] = None):
            if node.type == "class_definition":
                name_node = node.child_by_field_name("name")
                class_name = (
                    name_node.text.decode("utf-8") if name_node and name_node.text else None
                )
                for child in node.children:
                    traverse(child, class_name)
                return

            if node.type == "function_definition":
                name_node = node.child_by_field_name("name")
                func_name = (
                    name_node.text.decode("utf-8") if name_node and name_node.text else "anonymous"
                )
                start_line = node.start_point[0] + 1
                end_line = node.end_point[0] + 1
                snippet = code_bytes[node.start_byte : node.end_byte].decode("utf-8", errors="replace")

                nodes.append(
                    FunctionNode(
                        file_path=file_path,
                        function_name=func_name,
                        class_name=current_class,
                        language=Language.PYTHON,
                        start_line=start_line,
                        end_line=end_line,
                        code_snippet=snippet,
                    )
                )

            for child in node.children:
                traverse(child, current_class)

def detect_language(file_path: str) -> Optional[Language]:
    """Detect Language enum from file extension."""
    suffix = Path(file_path).suffix.lower()
    return EXTENSION_LANGUAGE_MAP.get(suffix)

def extract_diff_from_repo(repo_path: str, base_sha: str, head_sha: str) -> list[DiffHunk]:
